/* Lede look "brutal" (Neo-brutalist): the rules no token reaches. Its token values are in ./brutal.tokens.css, which the token build
   writes from `looks` in tokens/tokens.json. Turn it on with <ThemeProvider look="brutal">, or data-look="brutal" on a theme root.

   The rules sit in an @scope that stops at a theme root with another look or none, so they reach only what the look's own
   provider holds, as its tokens do. `:scope` stands for the look's root. Each rule is a candidate for the next token. */
/* The look's faces, from Fontsource. A browser downloads a face only once a page draws text in it. */
@import "@fontsource-variable/space-grotesk";
@import "./brutal.tokens.css";

/* ═════════════════════════════ NEO-BRUTALIST ("Poster") ═════════════════════════════
   Thick black outlines, hard offset shadows, flat loud fills, no curves, no blur and snappy motion. */
@scope ([data-look="brutal"]) to ([data-theme]:not([data-look="brutal"])) {
  /* Beyond tokens: a tinted Button is yellow, not a tint of the accent. A tint-color token would carry it. */
  :scope .ld-btn-tinted:not(.ld-btn-critical) { background-color: var(--secondary); color: var(--secondary-foreground); }
  :scope .ld-row-wrap + .ld-row-wrap::before { left: 0; }
  /* The avatar is a loud chip. High contrast keeps Lede's own, whose colours its palette sets. */
  @container style(--ld-contrast: standard) {
    :scope .ld-avatar { box-shadow: 0 0 0 2px var(--border); background: var(--ring); color: #000000; }
  }
  /* The open row is marked the way a selected segment is: filled, not only bold. */
  :scope .ld-row:has(.ld-row-target[aria-current="page"]) { background-image: linear-gradient(var(--fill-selected), var(--fill-selected)); }
}

/* Lede look "brutal" (Neo-brutalist) — GENERATED from tokens/tokens.json by scripts/build-tokens.mjs. Do not edit. */

@scope ([data-look="brutal"]) to ([data-look]:not([data-look="brutal"]) [data-theme]) {
  :where([data-theme][data-look]:not([data-look="brutal"])) {
    --radius: 22px;
    --radius-capsule: 999px;
    --radius-step: 8px;
    --blur-regular: 24px;
    --blur-thin: 12px;
    --blur-thick: 40px;
    --font-sans: -apple-system, BlinkMacSystemFont, system-ui, "Segoe UI", "Helvetica Neue", Arial, sans-serif;
    --weight-medium: 500;
    --weight-semibold: 600;
    --weight-bold: 700;
    --duration-standard: 240ms;
    --easing-spring: cubic-bezier(0.34, 1.4, 0.64, 1);
    --stroke-hairline: 0.5px;
    --stroke-input: 1px;
    --press-transform: initial;
    --case-label: none;
    --tracking-label: normal;
    --case-button: none;
    --case-title: none;
    --edge-surface: 0 0 transparent;
    --depth-control: 0 0 transparent;
    --depth-well: 0 0 transparent;
    --depth-pressed: inset 0 0 transparent;
  }
}

[data-theme][data-look="brutal"] {
  --radius: 0px;
  --radius-capsule: 0px;
  --radius-step: 0px;
  --blur-regular: 0px;
  --blur-thin: 0px;
  --blur-thick: 0px;
  --font-sans: "Space Grotesk Variable", "Helvetica Neue", Arial, sans-serif;
  --weight-medium: 600;
  --weight-semibold: 700;
  --weight-bold: 800;
  --duration-standard: 90ms;
  --easing-spring: steps(3, end);
  --stroke-hairline: 2px;
  --stroke-input: 2px;
  --press-transform: translate(3px, 3px);
  --case-label: uppercase;
  --tracking-label: 0.08em;
  --case-button: uppercase;
  --case-title: uppercase;
}

[data-theme^="light"][data-look="brutal"] {
  --edge-surface: 0 0 0 2px #000000, 4px 4px 0 #000000;
  --depth-control: 0 0 0 2px #000000, 3px 3px 0 #000000;
  --depth-well: 0 0 0 2px #000000;
  --depth-pressed: 0 0 0 2px #000000;
}

[data-theme="light"][data-look="brutal"] {
  --primary: #1f3dff;
  --primary-foreground: #ffffff;
  --background: #fffdf5;
  --background-grouped: #fff1c9;
  --card: #ffffff;
  --muted: #fbe9b7;
  --foreground: #000000;
  --muted-foreground: #3b3b3b;
  --secondary: #ffe066;
  --fill-control: #ffffff;
  --fill-control-strong: #ffe066;
  --fill-selected: #ffe066;
  --fill-knob: #ffffff;
  --border: #000000;
  --input: #000000;
  --ring: #f03977;
  --destructive: #d10f2f;
  --success: #0a7a2f;
  --warning: #8a5a00;
  --glass-tint: #ffffff;
  --glass-stroke: #000000;
  --glass-highlight: transparent;
  --shadow-raised: 3px 3px 0 #000000;
  --shadow-float: 0 0 0 2px #000000, 6px 6px 0 #000000;
  --shadow-knob: 0 0 0 2px #000000;
}

[data-theme^="dark"][data-look="brutal"] {
  --edge-surface: 0 0 0 2px #ffffff, 4px 4px 0 #ffffff;
  --depth-control: 0 0 0 2px #ffffff, 3px 3px 0 #ffffff;
  --depth-well: 0 0 0 2px #ffffff;
  --depth-pressed: 0 0 0 2px #ffffff;
}

[data-theme="dark"][data-look="brutal"] {
  --glass-highlight: transparent;
  --primary: #ffe066;
  --primary-foreground: #000000;
  --background: #111111;
  --background-grouped: #000000;
  --card: #1c1c1c;
  --muted: #262626;
  --foreground: #ffffff;
  --muted-foreground: #d4d4d4;
  --secondary: #8a003c;
  --secondary-foreground: #ffffff;
  --fill-control: #000000;
  --fill-control-strong: #3a3a3a;
  --fill-selected: #8a003c;
  --fill-knob: #ffffff;
  --border: #ffffff;
  --input: #ffffff;
  --ring: #4dd0ff;
  --destructive: #ff6675;
  --destructive-foreground: #000000;
  --success: #4dff8a;
  --warning: #ffc04d;
  --glass-tint: #000000;
  --glass-stroke: #ffffff;
  --shadow-raised: 3px 3px 0 #ffffff;
  --shadow-float: 0 0 0 2px #ffffff, 6px 6px 0 #ffffff;
  --shadow-knob: 0 0 0 2px #000000;
}
